    internal class LongestNonRepeatingSubstring : IExperiment
    {
        public void Experiment()
        {
            //string input = "asdfxcvxcviuyiuysdfsdddssaasdfsdf";
            //string input = "bbbbb"; // 1
            //string input = "abcabcbb"; // 3
            string input = "pwwkew"; // 3
            //string input = GetTheHugeString();
            //string input = "asdfertljk";

            List<string> allPossibleSubstrings = ProduceAllPossibleSubstrings(input);
            List<string> onlyNonRepeatingSubstrings = RemoveAnySubstringsWithRepeatingCharacters(allPossibleSubstrings);
            Int64 length = FindTheLongestOfAllPossibleSubstrings(onlyNonRepeatingSubstrings);
            Console.WriteLine(length);
        }

