        private List<string> RemoveAnySubstringsWithRepeatingCharacters(List<string> allPossibleSubstrings)
        {
            List<string> noRepeatSubstrings = new List<string>();

            foreach (string substring in allPossibleSubstrings)
            {
                bool matchFound = false;
                for (int i = 0; i < substring.Length; i++)
                {
                    // does char at i equal char at i + 1
                    for (int j = i+1; j < substring.Length; j++)
                    {
                        var first = substring[i];
                        var second = substring[j];
                        matchFound = first == second;
                        if (matchFound) break;
                    }
                    if (matchFound) break;
                }
                if (!matchFound) { noRepeatSubstrings.Add(substring); }
            }

            return noRepeatSubstrings;
        }

        private Int64 FindTheLongestOfAllPossibleSubstrings(List<string> onlyNonRepeatingSubstrings)
        {
            Int64 longest = 0;
            foreach (string substring in onlyNonRepeatingSubstrings)
            {
                if (substring.Length > longest) longest = substring.Length;
            }
            return longest;
        }

        private List<string> ProduceAllPossibleSubstrings(string input)
        {
            List<string> result = new List<string>();
            for (int i = 0; i < input.Length; i++)
            {
                for (int j = 1; j < input.Length; j++) 
                {
                    if (j + i > input.Length) break;
                    string substring = input.Substring(i, j);
                    Console.WriteLine(substring);
                    result.Add(substring);
                }

            }
            result.Add(input);
            return result;
        }
        public string IdentifyExperiment()
        {
            return "LongestNonRepeatingSubstring";
        }
